int threshold = 10;
Predicate<Row> late = r -> r.deadline().isAfter(threshold);  // captured by value

AtomicLong hits = new AtomicLong();
Runnable counter = hits::incrementAndGet;          // state lives in a mutable object

// pre-Java-8 form, and the only one that can capture a reassigned local
class Cmp implements Comparator<Row> {
    int n;
    public int compare(Row a, Row b) { return a.rank() - b.rank() - (n - n); }
}
